const frame = msg.payload || msg;
const canId = frame.canid;
const data = frame.data || [];

const msgType = (canId >> 8) & 0x0F;
const bmsAddr = canId & 0xFF;

if ((canId & 0x1FFFF000) !== 0x14F00000) {
    return null;
}

const contextKey = "bms_" + bmsAddr;
let bms = flow.get(contextKey) || {
    kind: "BmsCanState",
    version: 1,
    bmsAddress: bmsAddr
};

function u16(buf, offset) {
    return (buf[offset] & 0xFF) | ((buf[offset + 1] & 0xFF) << 8);
}

function s16(buf, offset) {
    var val = u16(buf, offset);
    return val > 0x7FFF ? val - 0x10000 : val;
}

switch (msgType) {
    case 1:
        bms.chargeDischargeStatus = data[0];
        bms.currentA = s16(data, 2) * 0.1;
        bms.batteryPackVoltageV = u16(data, 4) * 0.1;
        bms.batteryRemainingCapacityAh = u16(data, 6) * 0.01;
        break;
    case 2:
        bms.maxCellVoltageMv = u16(data, 0);
        bms.minCellVoltageMv = u16(data, 2);
        bms.avgCellVoltageMv = u16(data, 4);
        bms.avgCellTempC = s16(data, 6) * 0.1;
        break;
    case 3:
        bms.ratedCapacityAh = u16(data, 0) * 0.01;
        bms.totalDischargeWh = u16(data, 4);
        bms.cycleCount = u16(data, 6);
        break;
    case 4:
        bms.softwareVersionMain = data[0];
        bms.softwareVersionSub = data[1];
        bms.sohPercent = u16(data, 2);
        break;
    case 5:
        bms._sn1 = "";
        for (var i = 0; i < 8; i++) { if (data[i] === 0) break; bms._sn1 += String.fromCharCode(data[i]); }
        bms.serialNumber = (bms._sn1 || "") + (bms._sn2 || "") + (bms._sn3 || "");
        break;
    case 6:
        bms._sn2 = "";
        for (var j = 0; j < 8; j++) { if (data[j] === 0) break; bms._sn2 += String.fromCharCode(data[j]); }
        bms.serialNumber = (bms._sn1 || "") + (bms._sn2 || "") + (bms._sn3 || "");
        break;
    case 7:
        bms._sn3 = "";
        for (var k = 0; k < 8; k++) { if (data[k] === 0) break; bms._sn3 += String.fromCharCode(data[k]); }
        bms.serialNumber = (bms._sn1 || "") + (bms._sn2 || "") + (bms._sn3 || "");
        break;
    default:
        return null;
}

bms.timestampUtc = new Date().toISOString();
flow.set(contextKey, bms);
msg.payload = bms;
msg.topic = "bms/" + bmsAddr;
return msg;

const allBms = [];
for (var i = 1; i <= 16; i++) {
    var bms = flow.get("bms_" + i);
    if (bms) {
        var clean = Object.assign({}, bms);
        delete clean._sn1;
        delete clean._sn2;
        delete clean._sn3;
        allBms.push(clean);
    }
}
msg.payload = {
    kind: "BmsCanStateList",
    timestampUtc: new Date().toISOString(),
    bmsCount: allBms.length,
    bmsList: allBms
};
return msg;
